// Funktion zur Berechnung der n-ten Fibonacci-Zahl mit dynamischer Programmierung
int fibonacci(int n, vector<int>& memo) {
    if (n <= 1) {
        memo[n] = n;
        return n;
    }
    if (memo[n] != -1) {
        return memo[n];
    }
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo);
    return memo[n];
